custom.expression:
let hz = 0.04;
let sky_t = clamp((p.y - hz) / 0.46, 0.0, 1.0);
let sky_base = mix(c2 * 0.6, c4 * 0.8, sky_t);
let sun = c3 * halo(sd_circle(p - vec2<f32>(0.42, 0.16), 0.05), 0.28);
let sky_col = sky_base + c3 * smoothstep(0.2, 0.0, p.y - hz) * 0.45 + sun;
var birds = 0.0;
for (var i = 0; i < 5; i++) {
    let kb = f32(i);
    let bx = fract(t * 0.03 * bird_speed + kb * 0.19) * 2.0 - 1.0;
    let by = 0.22 + 0.06 * sin(t * 0.4 + kb * 2.1) + 0.03 * kb;
    let qb = p - vec2<f32>(bx, by);
    let flap = 0.012 * sin(t * 7.0 * bird_speed + kb * 1.7);
    let db = min(sd_segment(qb, vec2<f32>(-0.03, flap), vec2<f32>(0.0, 0.0)), sd_segment(qb, vec2<f32>(0.0, 0.0), vec2<f32>(0.03, flap))) - 0.002;
    birds = birds + (1.0 - smoothstep(0.0, 0.002, db));
}
let below = max(hz - p.y, 0.03);
let depth = 0.12 / below;
let wx = p.x * depth;
let wz = depth;
let far_w = sin(wx * 0.7 + sin(wz * 0.4 - t * 0.25 * wave_speed) * 1.5);
let mid_w = sin(wx * 1.1 + sin(wz * 0.7 - t * 0.4 * wave_speed) * 1.8 + 1.3);
let near_w = sin(wx * 1.9 + sin(wz * 1.1 - t * 0.6 * wave_speed) * 2.0 + 2.7);
let foam = clamp((smoothstep(0.75, 0.98, near_w) * 0.9 + smoothstep(0.8, 0.99, mid_w) * 0.4) * wave_height, 0.0, 1.0);
let base = mix(c2 * 0.9, c4 * 1.3, clamp(below * 2.0, 0.0, 1.0));
let tinted = base + c1 * (smoothstep(0.2, 1.0, far_w) * 0.25 + smoothstep(0.3, 1.0, mid_w) * 0.3) * wave_height;
let refl = exp(-abs(p.x - 0.42) * 6.0) * exp(-below * 5.0);
let lit = tinted + c3 * refl * (0.6 + 0.4 * near_w) * 0.5;
let ocean_foam = mix(lit, c5, foam * 0.8);
let haze = smoothstep(0.12, 0.0, below);
let ocean_haze = mix(ocean_foam, c3 * 0.6 + c2 * 0.4, haze * 0.6);
var fish = 0.0;
for (var j = 0; j < 4; j++) {
    let kf = f32(j);
    let fx = fract(t * 0.025 * fish_speed + kf * 0.31) * 2.2 - 1.1;
    let fy = -0.12 - 0.09 * fract(kf * 0.53) + 0.01 * sin(t * 3.0 + kf);
    let qf = p - vec2<f32>(fx, fy);
    let body = sd_circle(vec2<f32>(qf.x * 0.5, qf.y), 0.022);
    let tail = sd_segment(qf, vec2<f32>(-0.02, 0.0), vec2<f32>(-0.034, 0.012 * sin(t * 6.0 + kf * 2.0))) - 0.004;
    fish = fish + (1.0 - smoothstep(0.0, 0.003, min(body, tail)));
}
let ocean_col = mix(ocean_haze, c4 * 0.5, min(fish, 1.0) * 0.85);
let sky_final = mix(sky_col, c4 * 0.2, min(birds, 1.0) * 0.9);
let scene = mix(ocean_col, sky_final, step(hz, p.y));
return mix(bg, tonemap(scene), strength);
